"""Imitation minimale de la révision MCP 2026-07-28 sur stdio, en Python pur (ce n'est pas le SDK officiel)."""
import json
import subprocess
import sys

VERSION = "2026-07-28"


# ---------- Côté serveur : lit stdin ligne par ligne, répond sur stdout ----------
def tva(montant_ht, taux_pourcent):
    return round(montant_ht * (1 + taux_pourcent / 100), 2)


OUTILS = [{
    "name": "calculer_tva",
    "description": "Calcule le montant TTC à partir d'un montant HT et d'un taux en pourcentage.",
    "inputSchema": {
        "type": "object",
        "properties": {"montant_ht": {"type": "number"}, "taux_pourcent": {"type": "number"}},
        "required": ["montant_ht", "taux_pourcent"],
    },
}]


def erreur(id_, code, message, data=None):
    err = {"code": code, "message": message}
    if data is not None:
        err["data"] = data
    return {"jsonrpc": "2.0", "id": id_, "error": err}


def traiter(msg):
    id_, params = msg.get("id"), msg.get("params", {})
    meta = params.get("_meta", {})
    if "io.modelcontextprotocol/protocolVersion" not in meta or "io.modelcontextprotocol/clientCapabilities" not in meta:
        return erreur(id_, -32602, "Invalid params : _meta incomplet")
    if meta["io.modelcontextprotocol/protocolVersion"] != VERSION:
        return erreur(id_, -32022, "Unsupported protocol version",
                      {"supported": [VERSION], "requested": meta["io.modelcontextprotocol/protocolVersion"]})
    info = {"io.modelcontextprotocol/serverInfo": {"name": "mini-serveur", "version": "0.1"}}
    if msg["method"] == "server/discover":
        res = {"supportedVersions": [VERSION], "capabilities": {"tools": {}}, "instructions": "Un seul outil, pour l'exemple."}
    elif msg["method"] == "tools/list":
        res = {"tools": OUTILS, "ttlMs": 60000, "cacheScope": "public"}
    elif msg["method"] == "tools/call" and params.get("name") == "calculer_tva":
        a = params.get("arguments", {})
        if not isinstance(a.get("montant_ht"), (int, float)) or not isinstance(a.get("taux_pourcent"), (int, float)):
            res = {"content": [{"type": "text", "text": "Arguments invalides : deux nombres sont attendus."}], "isError": True}
        else:
            res = {"content": [{"type": "text", "text": f"Montant TTC : {tva(a['montant_ht'], a['taux_pourcent']):.2f}"}], "isError": False}
    elif msg["method"] == "tools/call":
        return erreur(id_, -32602, f"Unknown tool: {params.get('name')}")
    else:
        return erreur(id_, -32601, "Method not found")
    return {"jsonrpc": "2.0", "id": id_, "result": {"resultType": "complete", **res, "_meta": info}}


def serveur():
    for ligne in sys.stdin:  # un message JSON par ligne
        if ligne.strip():
            sys.stdout.write(json.dumps(traiter(json.loads(ligne)), ensure_ascii=False) + "\n")
            sys.stdout.flush()
    print("stdin fermé, arrêt", file=sys.stderr)  # les journaux vont sur stderr, jamais sur stdout


# ---------- Côté client : lance le serveur comme sous-processus ----------
def client():
    proc = subprocess.Popen([sys.executable, __file__, "serveur"], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                            text=True, encoding="utf-8", stderr=subprocess.DEVNULL)
    meta = {"io.modelcontextprotocol/protocolVersion": VERSION, "io.modelcontextprotocol/clientCapabilities": {}}

    def appel(id_, methode, params=None, meta_=meta):
        msg = {"jsonrpc": "2.0", "id": id_, "method": methode, "params": {**(params or {}), "_meta": meta_}}
        print("->", json.dumps(msg, ensure_ascii=False))
        proc.stdin.write(json.dumps(msg, ensure_ascii=False) + "\n")
        proc.stdin.flush()
        print("<-", proc.stdout.readline().strip())

    appel(1, "server/discover")
    appel(2, "tools/list")
    appel(3, "tools/call", {"name": "calculer_tva", "arguments": {"montant_ht": 150, "taux_pourcent": 20}})
    appel(4, "tools/call", {"name": "calculer_tva", "arguments": {"montant_ht": "cent"}})
    appel(5, "tools/call", {"name": "inconnu", "arguments": {}})
    appel(6, "tools/list", meta_={**meta, "io.modelcontextprotocol/protocolVersion": "1900-01-01"})
    proc.stdin.close()  # fermer stdin est le signal d'arrêt normal
    proc.wait(timeout=5)


if __name__ == "__main__":
    for flux in (sys.stdin, sys.stdout):  # MCP échange de l'UTF-8, quel que soit l'encodage par défaut du système
        flux.reconfigure(encoding="utf-8")
    serveur() if sys.argv[1:] == ["serveur"] else client()

